def backfill_blocks(apps, schema_editor):
    Version = apps.get_model("capture", "DocumentVersion")
    Block = apps.get_model("capture", "TextBlock")
    for version in (
        Version.objects.using(schema_editor.connection.alias)
        .only("id", "text")
        .iterator(chunk_size=100)
    ):
        rows, start = [], 0
        while start < len(version.text):
            end = min(start + 1000, len(version.text))
            if end < len(version.text):
                boundary = version.text.rfind("\n", start + 500, end)
                if boundary >= start:
                    end = boundary + 1
            rows.append(
                Block(
                    version_id=version.id,
                    index=len(rows),
                    start_offset=start,
                    end_offset=end,
                    text=version.text[start:end],
                )
            )
            start = end
        Block.objects.using(schema_editor.connection.alias).bulk_create(
            rows, batch_size=100
        )


